import { SessionManager, type SessionEntry } from "@earendil-works/pi-coding-agent";
import type { ImageContent, TextContent } from "@earendil-works/pi-ai";

type DisplayContent = string | (TextContent | ImageContent)[];
type ToolArguments = Record<string, unknown>;

interface TranscriptPart {
    text: string;
    toolOnly: boolean;
}

function contentText(content: DisplayContent): string {
    if (typeof content === "string") return content;
    return content.map((block) => (
        block.type === "text" ? block.text : `[image: ${block.mimeType}]`
    )).join("\n");
}

function quoteText(text: string): string {
    return text.split("\n").map((line) => `> ${line}`).join("\n");
}

function stringArgument(args: ToolArguments, name: string): string | undefined {
    const value = args[name];
    return typeof value === "string" ? value : undefined;
}

function changeLines(prefix: "+" | "-", text: string): string[] {
    return text.split("\n").map((line) => `  ${prefix} ${line}`);
}

function editCall(args: ToolArguments, prefix: string): string[] {
    const lines = [`${prefix} edit ${stringArgument(args, "path") ?? ""}`.trimEnd()];
    const edits = args.edits;
    if (!Array.isArray(edits)) return lines;

    for (const edit of edits) {
        if (!edit || typeof edit !== "object") continue;
        const { oldText, newText } = edit as { oldText?: unknown; newText?: unknown };
        if (typeof oldText === "string") lines.push(...changeLines("-", oldText));
        if (typeof newText === "string") lines.push(...changeLines("+", newText));
    }
    return lines;
}

function toolCallText(name: string, args: ToolArguments, failed: boolean): string {
    // × matches the failure marker already used by the agent activity widget.
    const prefix = failed ? "×" : "●";
    switch (name) {
        case "edit":
            return editCall(args, prefix).join("\n");
        case "bash":
            return `${prefix} bash ${stringArgument(args, "command") ?? ""}`.trimEnd();
        default: {
            const path = stringArgument(args, "path");
            return path ? `${prefix} ${name} ${path}` : `${prefix} ${name}`;
        }
    }
}

function messageText(
    entry: Extract<SessionEntry, { type: "message" }>,
    failedToolCalls: ReadonlySet<string>,
): TranscriptPart | undefined {
    const { message } = entry;
    switch (message.role) {
        case "user":
            return { text: quoteText(contentText(message.content)), toolOnly: false };
        case "assistant": {
            const sections: string[] = [];
            const toolCalls: string[] = [];
            let hasText = false;
            const flushToolCalls = () => {
                if (toolCalls.length > 0) sections.push(toolCalls.splice(0).join("\n"));
            };
            for (const block of message.content) {
                if (block.type === "text") {
                    flushToolCalls();
                    sections.push(block.text);
                    hasText = true;
                } else if (block.type === "toolCall") {
                    toolCalls.push(toolCallText(
                        block.name,
                        block.arguments,
                        failedToolCalls.has(block.id),
                    ));
                }
                // Thinking blocks are deliberately omitted until this view gains
                // an explicit opt-in control for them.
            }
            flushToolCalls();
            const text = sections.filter(Boolean).join("\n\n");
            return text ? { text, toolOnly: !hasText } : undefined;
        }
        case "toolResult":
            // Tool calls provide the useful chronological trace without repeating
            // potentially large read/bash output already available elsewhere.
            return undefined;
        case "bashExecution":
            return {
                text: `${message.exitCode && message.exitCode !== 0 ? "×" : "●"} bash ${message.command}`,
                toolOnly: true,
            };
        case "custom":
            return { text: quoteText(contentText(message.content)), toolOnly: false };
        case "branchSummary":
            return { text: message.summary, toolOnly: false };
        case "compactionSummary":
            return { text: message.summary, toolOnly: false };
    }
}

function failedToolCallIds(entries: SessionEntry[]): Set<string> {
    const failed = new Set<string>();
    for (const entry of entries) {
        if (entry.type === "message" && entry.message.role === "toolResult" && entry.message.isError) {
            failed.add(entry.message.toolCallId);
        }
    }
    return failed;
}

/**
 * Formats an active delegated-child conversation for the read-only agent browser.
 * It keeps user/custom/assistant messages and compact tool calls in chronological
 * order. Edit calls show removed/added lines, failures use ×, and consecutive
 * tool-only responses stay together. Model thinking and tool-result output are omitted.
 */
export function formatAgentSessionTranscript(entries: SessionEntry[]): string {
    const failedToolCalls = failedToolCallIds(entries);
    const parts: TranscriptPart[] = [];
    for (const entry of entries) {
        if (entry.type === "message") {
            const part = messageText(entry, failedToolCalls);
            if (part) parts.push(part);
        } else if (entry.type === "custom_message") {
            parts.push({ text: quoteText(contentText(entry.content)), toolOnly: false });
        } else if (entry.type === "compaction") {
            parts.push({ text: entry.summary, toolOnly: false });
        } else if (entry.type === "branch_summary") {
            parts.push({ text: entry.summary, toolOnly: false });
        }
    }

    let transcript = "";
    let previousWasToolOnly = false;
    for (const part of parts) {
        if (transcript) transcript += previousWasToolOnly && part.toolOnly ? "\n" : "\n\n";
        transcript += part.text;
        previousWasToolOnly = part.toolOnly;
    }
    return transcript;
}

/** Returns the complete display transcript for a persisted child session, if readable. */
export function loadAgentSessionTranscript(sessionFile: string): string | undefined {
    try {
        return formatAgentSessionTranscript(SessionManager.open(sessionFile).getBranch());
    } catch {
        return undefined;
    }
}

import fs from "node:fs/promises";
import path from "node:path";
import {
    SessionManager,
    type SessionInfo,
} from "@earendil-works/pi-coding-agent";

import { PI_CODER_AGENT_SESSIONS_DIR } from "../../../common/constants";
import { getAgentCwdSessionDir } from "../runs/persistence";
import { deriveAgentTitle } from "../runs/manager";
import type { AgentRunSummary } from "../contracts/runs";
import type { AgentRunCatalogRecord } from "../contracts/workspaces";
import { listAgentRunCatalog } from "../storage/run-catalog";
import type { AgentSessionBrowserItem } from "./browser-models";
import { loadAgentSessionTranscript } from "./transcript";

function currentItem(run: AgentRunSummary): AgentSessionBrowserItem {
    return {
        kind: "current",
        id: run.runId,
        title: run.title,
        agent: run.agent,
        status: run.status,
        task: run.task,
        startedAt: run.startedAt,
        updatedAt: run.updatedAt,
        sessionFile: run.sessionFile,
        activity: run.activity,
        responsePreview: run.responsePreview,
        mutating: run.mutating,
        usage: run.usage,
        changedFiles: run.mutationReport?.changedFiles,
        readFiles: run.mutationReport?.readFiles,
    };
}

function historicalStatus(status: string | undefined): string | undefined {
    // A past transcript has no live child handle in this runtime. Persisted
    // startup/running states therefore describe an interrupted run, not one
    // that is still executing.
    return status === "starting" || status === "running" || status === "waiting_for_permission"
        ? "interrupted"
        : status;
}

function pastItem(
    info: SessionInfo,
    parentSessionId: string,
    metadata: AgentRunCatalogRecord | undefined,
): AgentSessionBrowserItem {
    return {
        kind: "past",
        id: info.id,
        title: metadata?.title ?? deriveAgentTitle(info.firstMessage),
        agent: metadata?.agent ?? "delegated agent",
        status: historicalStatus(metadata?.status) ?? "historical",
        task: metadata?.task ?? info.firstMessage,
        startedAt: metadata?.startedAt,
        updatedAt: metadata?.updatedAt ?? info.modified.getTime(),
        sessionFile: info.path,
        parentSessionId,
        messageCount: info.messageCount,
        firstMessage: info.firstMessage,
        allMessagesText: info.allMessagesText.slice(-4_000),
        transcript: loadAgentSessionTranscript(info.path) ?? info.allMessagesText,
        mutating: metadata?.mutating,
        usage: metadata?.usageSnapshot,
        responsePreview: metadata?.responsePreview,
        changedFiles: metadata?.mutationReport?.changedFiles,
        readFiles: metadata?.mutationReport?.readFiles,
    };
}

export function currentAgentSessionItems(runs: AgentRunSummary[]): AgentSessionBrowserItem[] {
    return runs.map(currentItem);
}

/** Load complete human-readable transcripts for current runs whose files exist. */
export async function loadAgentSessionTranscripts(
    items: AgentSessionBrowserItem[],
): Promise<AgentSessionBrowserItem[]> {
    const directoryInfos = new Map<string, Promise<SessionInfo[]>>();
    const infosFor = (directory: string): Promise<SessionInfo[]> => {
        let promise = directoryInfos.get(directory);
        if (!promise) {
            promise = SessionManager.listAll(directory).catch(() => []);
            directoryInfos.set(directory, promise);
        }
        return promise;
    };

    return Promise.all(items.map(async (item) => {
        if (!item.sessionFile || item.transcript !== undefined) return item;
        const directory = path.dirname(item.sessionFile);
        const info = (await infosFor(directory)).find(
            (candidate) => path.resolve(candidate.path) === path.resolve(item.sessionFile!),
        );
        return info
            ? { ...item, transcript: loadAgentSessionTranscript(info.path) ?? info.allMessagesText }
            : item;
    }));
}

export async function listPastAgentSessions(
    cwd: string,
    agentSessionsDir?: string,
): Promise<AgentSessionBrowserItem[]> {
    const cwdSessionDir = getAgentCwdSessionDir(cwd, agentSessionsDir);
    const workspacesDir = path.join(
        path.dirname(path.resolve(agentSessionsDir ?? PI_CODER_AGENT_SESSIONS_DIR)),
        "workspaces",
    );
    let entries;
    try {
        entries = await fs.readdir(cwdSessionDir, { withFileTypes: true });
    } catch {
        return [];
    }

    const parentDirectories = entries
        .filter((entry) => entry.isDirectory())
        .map((entry) => entry.name)
        .sort();
    const sessions: AgentSessionBrowserItem[] = [];
    for (const parentSessionId of parentDirectories) {
        const directory = path.join(cwdSessionDir, parentSessionId);
        let infos: SessionInfo[];
        try {
            infos = await SessionManager.listAll(directory);
        } catch {
            continue;
        }
        const catalog = await listAgentRunCatalog(cwd, workspacesDir);
        sessions.push(...infos.map((info) => {
            const metadata = catalog.find((record) => (
                record.ownerSessionId === parentSessionId
                && record.childSessionFile !== undefined
                && path.resolve(record.childSessionFile) === path.resolve(info.path)
            ));
            return pastItem(info, parentSessionId, metadata);
        }));
    }

    sessions.sort((a, b) => b.updatedAt - a.updatedAt);
    return sessions;
}

export function removeCurrentAgentTranscripts(
    past: AgentSessionBrowserItem[],
    current: AgentSessionBrowserItem[],
): AgentSessionBrowserItem[] {
    const currentFiles = new Set(
        current
            .map((item) => item.sessionFile && path.resolve(item.sessionFile))
            .filter((file): file is string => file !== undefined),
    );
    return past.filter((item) => !item.sessionFile || !currentFiles.has(path.resolve(item.sessionFile)));
}

