import type { ExtensionAPI, ExtensionCommandContext } from "@earendil-works/pi-coding-agent";

import type { AgentWorkspace } from "./contracts/workspaces";
import { emitAgentEvent } from "./observability/events";
import {
    type AgentSessionBrowserItem,
    workspaceBrowserItem,
} from "./presentation/browser-models";
import {
    currentAgentSessionItems,
    listPastAgentSessions,
    loadAgentSessionTranscripts,
    removeCurrentAgentTranscripts,
} from "./presentation/sessions";
import {
    showAgentSessionBrowser,
    type AgentSessionBrowserData,
} from "../../tui/agent-session-browser";
import type { AgentLifecycle } from "./lifecycle";
import { prepareForegroundWorkspaceResult } from "./workspaces/finalization";
import { inspectAgentWorkspaceDiff, reconcileNoChangeAgentWorkspaceLeases } from "./workspaces/results";
import { inspectAgentWorkspaceGitState, listAgentWorkspaces } from "./workspaces/store";
import { handleWorkspaceAction } from "./workspaces/tui-actions";

export function registerAgentBrowser(pi: ExtensionAPI, lifecycle: AgentLifecycle): void {
    const showAgentBrowser = async (_args: string, ctx: ExtensionCommandContext) => {
        const currentSessionId = ctx.sessionManager.getSessionId();
        let workspaceDomains = new Map<string, AgentWorkspace>();
        const requireWorkspace = (workspaceId: string): AgentWorkspace => {
            const workspace = workspaceDomains.get(workspaceId);
            if (!workspace) throw new Error(`Workspace ${workspaceId} is no longer available.`);
            return workspace;
        };
        const loadBrowserData = async (): Promise<AgentSessionBrowserData> => {
            await lifecycle.manager.flushPersistence();
            const current = await loadAgentSessionTranscripts(
                currentAgentSessionItems([
                    ...lifecycle.manager.listRuns(),
                    ...lifecycle.setupRunSummaries,
                ]),
            );
            let past: AgentSessionBrowserItem[];
            try {
                past = removeCurrentAgentTranscripts(
                    await listPastAgentSessions(ctx.cwd),
                    current,
                );
            } catch (error) {
                const message = error instanceof Error ? error.message : String(error);
                ctx.ui.notify(`Could not browse persisted delegated-agent sessions: ${message}`, "warning");
                past = [];
            }
            let workspaceRecords: AgentWorkspace[];
            try {
                // Reconcile only verified no-change results. Changed or otherwise
                // uncertain leases remain protected until an explicit action.
                const released = await reconcileNoChangeAgentWorkspaceLeases(ctx.cwd);
                if (released > 0) {
                    ctx.ui.notify(
                        `Released ${released} verified no-change workspace lease${released === 1 ? "" : "s"}.`,
                        "info",
                    );
                    emitAgentEvent(lifecycle.events, ctx.cwd, {
                        type: "runtime",
                        action: "reconciled",
                        released,
                    });
                }
                workspaceRecords = await listAgentWorkspaces(ctx.cwd);
            } catch (error) {
                const message = error instanceof Error ? error.message : String(error);
                ctx.ui.notify(`Could not browse agent workspaces: ${message}`, "warning");
                workspaceRecords = [];
            }
            workspaceDomains = new Map(workspaceRecords.map((workspace) => [workspace.id, workspace]));
            const workspaces = await Promise.all(workspaceRecords.map(async (workspace) => workspaceBrowserItem(
                workspace,
                await inspectAgentWorkspaceGitState(workspace),
                currentSessionId,
            )));
            return { current, past, workspaces };
        };

        const initial = await loadBrowserData();
        await showAgentSessionBrowser({
            ...initial,
            cwd: ctx.cwd,
            eventBus: pi.events,
            onRefresh: loadBrowserData,
            onResume: async (item) => {
                try {
                    const outcome = await prepareForegroundWorkspaceResult(
                        await lifecycle.manager.resume(
                            item.id,
                            undefined,
                            undefined,
                            lifecycle.backgroundUpdate(ctx),
                        ),
                        ctx,
                        lifecycle.events,
                    );
                    lifecycle.clearCompletedWorkspaceSetup(ctx, outcome.details);
                    lifecycle.refreshAgentUi(ctx);
                } catch (error) {
                    const message = error instanceof Error ? error.message : String(error);
                    ctx.ui.notify(`Could not resume ${item.id}: ${message}`, "warning");
                }
            },
            onCancel: async (item) => {
                try {
                    const outcome = await prepareForegroundWorkspaceResult(
                        await lifecycle.manager.cancel(item.id),
                        ctx,
                        lifecycle.events,
                    );
                    lifecycle.notifyUserCanceled(outcome.details);
                    lifecycle.refreshAgentUi(ctx);
                } catch (error) {
                    const message = error instanceof Error ? error.message : String(error);
                    ctx.ui.notify(`Could not cancel ${item.id}: ${message}`, "warning");
                }
            },
            onWorkspaceInspect: async (item) => inspectAgentWorkspaceDiff(requireWorkspace(item.id)),
            onWorkspaceAction: async (item, action) => {
                const workspace = requireWorkspace(item.id);
                const replacement = await handleWorkspaceAction(
                    workspace,
                    action,
                    ctx,
                    lifecycle.manager,
                );
                if (replacement !== workspace) {
                    if (action === "discard") {
                        lifecycle.emitWorkspaceEvent(ctx, workspace.id, "removed", action);
                    } else {
                        lifecycle.emitWorkspaceEvent(ctx, workspace.id, "updated", action);
                        if (action === "apply" || action === "retain") {
                            lifecycle.emitWorkspaceEvent(ctx, workspace.id, "result_changed", action);
                        }
                        if (
                            action === "apply"
                            || action === "retain"
                            || action === "reset"
                            || action === "release"
                            || action === "recover"
                        ) {
                            lifecycle.emitWorkspaceEvent(ctx, workspace.id, "lease_changed", action);
                        }
                    }
                }
                if (!replacement) {
                    workspaceDomains.delete(workspace.id);
                    return replacement;
                }
                workspaceDomains.set(replacement.id, replacement);
                return workspaceBrowserItem(
                    replacement,
                    await inspectAgentWorkspaceGitState(replacement),
                    currentSessionId,
                );
            },
        }, ctx);
    };

    pi.registerCommand("agents", {
        description: "Browse delegated agents and isolated workspaces",
        handler: showAgentBrowser,
    });
}

import type { Usage } from "@earendil-works/pi-ai";

import type {
    AgentWorkspace,
    AgentWorkspaceAction,
    AgentWorkspaceGitState,
} from "../contracts/workspaces";

export type { AgentWorkspaceAction } from "../contracts/workspaces";

export interface AgentSessionBrowserItem {
    kind: "current" | "past" | "empty";
    id: string;
    title: string;
    agent: string;
    status: string;
    task: string;
    startedAt?: number;
    updatedAt: number;
    sessionFile?: string;
    parentSessionId?: string;
    messageCount?: number;
    firstMessage?: string;
    allMessagesText?: string;
    transcript?: string;
    activity?: string;
    responsePreview?: string;
    mutating?: boolean;
    usage?: Usage;
    changedFiles?: string[];
    readFiles?: string[];
}

export type WorkspaceDispositionAction = Exclude<AgentWorkspaceAction, "inspect">;

export interface AgentWorkspaceBrowserAction {
    action: AgentWorkspaceAction;
    key: string;
    label: string;
}

export interface AgentWorkspaceGitView {
    kind: "available" | "unavailable";
    dirty: boolean;
    changedFiles?: number;
    stagedFiles?: number;
    unstagedFiles?: number;
    untrackedFiles?: number;
    headRevision?: string;
    error?: string;
    text: string;
}

export interface AgentWorkspaceBrowserItem {
    kind: "workspace";
    id: string;
    slug: string;
    cwd: string;
    repositoryRoot: string;
    worktreePath: string;
    baseRevision: string;
    status: "available" | "review_required";
    statusText: string;
    setupText: string;
    setupSummary?: string;
    leaseRunId?: string;
    leaseOwnerSessionId?: string;
    leaseAcquiredAt?: number;
    leaseText: string;
    leased: boolean;
    createdAt: number;
    updatedAt: number;
    git?: AgentWorkspaceGitView;
    actions: AgentWorkspaceBrowserAction[];
    notice: string;
}

function gitText(gitState: AgentWorkspaceGitState | undefined): string {
    if (!gitState) return "unknown";
    if (gitState.kind === "unavailable") {
        return `unavailable · ${gitState.error ?? "not a Git worktree"}`;
    }
    if (!gitState.dirty) return "clean";
    const files = gitState.changedFiles ?? 0;
    return `dirty · ${files} changed file${files === 1 ? "" : "s"}`;
}

function workspaceActions(
    workspace: AgentWorkspace,
    currentSessionId?: string,
): AgentWorkspaceBrowserAction[] {
    const actions: AgentWorkspaceBrowserAction[] = [];
    const ownedByAnotherSession = currentSessionId !== undefined
        && workspace.leaseOwnerSessionId !== undefined
        && workspace.leaseOwnerSessionId !== currentSessionId;
    const orphanedByAnotherSession = workspace.leaseState === "orphaned" && ownedByAnotherSession;
    if (orphanedByAnotherSession) {
        actions.push({ action: "recover", key: "x", label: "recover orphaned lease" });
    }
    if (workspace.latestResult && workspace.latestResult.status !== "discarded") {
        actions.push({ action: "inspect", key: "i", label: "inspect diff" });
    }
    if (ownedByAnotherSession) return actions;

    const currentResult = workspace.leaseRunId
        && workspace.latestResult?.runId === workspace.leaseRunId
        ? workspace.latestResult
        : undefined;
    const changed = Boolean(
        currentResult?.status === "prepared"
        && (
            currentResult.workerHead !== currentResult.baseRevision
            || currentResult.commits.length > 0
        )
    );
    if (changed) {
        actions.push(
            { action: "apply", key: "a", label: "apply" },
            { action: "retain", key: "t", label: "retain" },
        );
    }
    if (!workspace.leaseKind || workspace.leaseKind === "task") {
        if (workspace.leaseRunId && !currentResult) {
            actions.push(
                { action: "release", key: "l", label: "release stale lease" },
                { action: "discard", key: "d", label: "discard" },
            );
        } else if (!workspace.leaseRunId || workspace.latestResult) {
            actions.push(
                { action: "reset", key: "r", label: "reset" },
                { action: "discard", key: "d", label: "discard" },
            );
        }
    }
    return actions;
}

function workspaceNotice(workspace: AgentWorkspace, currentSessionId?: string): string {
    const ownedByAnotherSession = currentSessionId !== undefined
        && workspace.leaseOwnerSessionId !== undefined
        && workspace.leaseOwnerSessionId !== currentSessionId;
    if (workspace.leaseState === "orphaned" && ownedByAnotherSession) {
        return "The recorded run is no longer present in the durable run catalog. The lease and result remain protected until explicit recovery.";
    }
    if (workspace.leaseState === "orphaned") {
        return "The recorded run is no longer present in the durable run catalog, but this session has recovered control of the lease.";
    }
    if (ownedByAnotherSession) {
        return "This workspace is leased by another parent session and remains protected until that session dispositions its run.";
    }
    if (workspace.leaseRunId) {
        return "This workspace is leased and cannot be selected until its current run is explicitly dispositioned.";
    }
    if (workspace.status === "review_required") {
        return "This workspace requires explicit review before it can be reused.";
    }
    return "This workspace may be selected for an isolated worker.";
}

export function workspaceBrowserItem(
    workspace: AgentWorkspace,
    gitState?: AgentWorkspaceGitState,
    currentSessionId?: string,
): AgentWorkspaceBrowserItem {
    const leaseKind = workspace.leaseKind ?? "unknown";
    const orphaned = workspace.leaseState === "orphaned" ? " · orphaned" : "";
    return {
        kind: "workspace",
        id: workspace.id,
        slug: workspace.slug,
        cwd: workspace.cwd,
        repositoryRoot: workspace.repositoryRoot,
        worktreePath: workspace.worktreePath,
        baseRevision: workspace.baseRevision,
        status: workspace.status,
        statusText: workspace.leaseState === "orphaned"
            ? "orphaned lease"
            : workspace.leaseRunId
                ? "leased"
                : workspace.status.replaceAll("_", " "),
        setupText: workspace.setupState.replaceAll("_", " "),
        setupSummary: workspace.setupSummary,
        leaseRunId: workspace.leaseRunId,
        leaseOwnerSessionId: workspace.leaseOwnerSessionId,
        leaseAcquiredAt: workspace.leaseAcquiredAt,
        leaseText: workspace.leaseRunId
            ? `${leaseKind} · ${workspace.leaseRunId}${orphaned}`
            : "none",
        leased: Boolean(workspace.leaseRunId),
        createdAt: workspace.createdAt,
        updatedAt: workspace.updatedAt,
        git: gitState ? {
            ...gitState,
            dirty: gitState.dirty ?? false,
            text: gitText(gitState),
        } : undefined,
        actions: workspaceActions(workspace, currentSessionId),
        notice: workspaceNotice(workspace, currentSessionId),
    };
}

/**
 * Pager Component
 *
 * A read-only scrollable list. Unlike select/multi-select it has no cursor —
 * scrolling is driven externally (via state.scrollOffset and the onKey hook).
 * Built on ListViewComponent.
 */

import type { ExtensionCommandContext, Theme } from "@earendil-works/pi-coding-agent";
import type { Container } from "@earendil-works/pi-tui";
import { matchesKey } from "@earendil-works/pi-tui";
import type { ItemPrefix, ListItem, ListViewRenderItemOptions, ListViewState } from "./list-view";
import { ListViewComponent } from "./list-view";

// An item in the pager
export type PagerItem<T> = ListItem<T>;

// Options passed to renderItem callback
export interface RenderItemOptions<T> {
    index: number;
    theme: Theme;
    state: PagerState<T>;
}

// Options for the pager component
export interface PagerOptions<T> {
    // Title shown at the top
    title: string;
    // Items to display
    items: PagerItem<T>[];
    // Which line to start displaying from (scroll offset)
    scrollOffset: number;
    // Maximum visible lines before scrolling
    maxVisibleLines?: number;
    // Horizontal padding for content (default: 2)
    paddingX?: number;
    // Vertical padding for content (default: 0)
    paddingY?: number;
    // Custom render function for item content
    renderItem?: (item: PagerItem<T>, options: RenderItemOptions<T>) => string;
    // Optional header content rendered after title
    headerContent?: (container: Container, theme: Theme) => void;
    // Optional footer content rendered before help text
    footerContent?: (container: Container, theme: Theme, state: PagerState<T>) => void;
    // Custom help text
    helpText?: string;
    // Optional fixed total frame height, evaluated on each render
    fixedHeight?: () => number;
    // Remove the blank rows around the help footer
    compactFooter?: boolean;
    // Hook to intercept keys. Return true to indicate key was handled, or { done: true } to close the pager.
    onKey?: (key: string, state: PagerState<T>) => boolean | { done: boolean };
}

// Internal state for the pager
export interface PagerState<T> extends ListViewState<T> {
    // Pagers have no cursor — scrolling is externally driven
    cursor: null;
}

/**
 * PagerComponent - A scrollable list display component.
 *
 * Renders a list of items with scrolling support, title, help text,
 * and optional header/footer content.
 */
export class PagerComponent<T> extends ListViewComponent<T, void, PagerState<T>> {
    constructor(
        public readonly options: PagerOptions<T>,
    ) {
        super(
            {
                title: options.title,
                renderItem: options.renderItem
                    ? (item, renderOptions: ListViewRenderItemOptions<T, PagerState<T>>) =>
                        options.renderItem!(item, {
                            index: renderOptions.index,
                            theme: renderOptions.theme,
                            state: renderOptions.state,
                        })
                    : undefined,
                headerContent: options.headerContent,
                footerContent: options.footerContent,
                helpText: options.helpText ?? "Esc close",
                onKey: options.onKey,
                paddingX: options.paddingX,
                paddingY: options.paddingY,
                fixedHeight: options.fixedHeight,
                compactFooter: options.compactFooter,
            },
            {
                items: options.items,
                cursor: null,
                scrollOffset: options.scrollOffset,
                maxVisibleLines: options.maxVisibleLines ?? 10,
            },
        );
    }

    // Pager items render without any cursor/prefix decoration
    protected override getItemPrefix(_index: number, _isCursor: boolean): ItemPrefix {
        return { first: "", continuation: "" };
    }

    protected override handleAction(key: string): void {
        if (matchesKey(key, "escape") || key === "q") {
            this.finish(undefined);
            return;
        }
    }
}

// Show pager UI and return when closed
export async function pager<T>(
    options: PagerOptions<T>,
    ctx: ExtensionCommandContext,
): Promise<void> {
    if (!ctx.hasUI) {
        return;
    }

    if (options.items.length === 0) {
        return;
    }

    await ctx.ui.custom<void>((_tui, theme, _kb, done) => {
        const component = new PagerComponent(options);
        component.setDoneCallback(() => done());
        component.initialize(theme);

        return component;
    });
}

